// Se ejecuta al deployar — cargar config
const SUPABASE_URL = 'http://ingenio-kong:8000';
const SUPABASE_KEY = 'PEGAR_SUPABASE_SERVICE_ROLE_KEY_AQUI';
flow.set('sb_url', SUPABASE_URL);
flow.set('sb_key', SUPABASE_KEY);

func:
const url = flow.get('sb_url');
const key = flow.get('sb_key');
msg.url = url + '/rest/v1/paradas_inferidas?fin=is.null&order=inicio_sensor.desc&limit=1';
msg.method = 'GET';
msg.headers = {
    'apikey': key,
    'Authorization': 'Bearer ' + key
};
msg.payload = '';
return msg;

const rows = msg.payload;
const ctx = {
    segundos_parado: 0,
    parada_id: null,
    inicio_sensor: null,
    iniciado: true
};
if (Array.isArray(rows) && rows.length > 0) {
    ctx.parada_id = rows[0].id;
    ctx.inicio_sensor = rows[0].inicio_sensor;
    ctx.segundos_parado = 999;
    node.status({fill:'red', shape:'dot', text:'Parada abierta id=' + ctx.parada_id});
} else {
    node.status({fill:'green', shape:'dot', text:'Sin parada abierta'});
}
flow.set('trapiche_ctx', ctx);
return null;

const UMBRAL = 60;
const url = flow.get('sb_url');
const key = flow.get('sb_key');

let ctx = flow.get('trapiche_ctx');
if (!ctx || !ctx.iniciado) {
    node.status({fill:'grey', shape:'ring', text:'Esperando init...'});
    return null;
}

const estado = Number(msg.payload);

if (estado === 0) {
    if (!ctx.inicio_sensor) {
        ctx.inicio_sensor = new Date().toISOString();
    }
    ctx.segundos_parado++;
    node.status({fill:'red', shape:'ring', text:'Parado: ' + ctx.segundos_parado + 's' + (ctx.parada_id ? ' (registrado)' : ' (esperando 60s)') });

    if (ctx.segundos_parado === UMBRAL && !ctx.parada_id) {
        const body = {
            inicio_sensor: ctx.inicio_sensor,
            inicio_confirmado: new Date().toISOString()
        };
        flow.set('trapiche_ctx', ctx);
        return [{
            method: 'POST',
            url: url + '/rest/v1/paradas_inferidas',
            headers: {
                'apikey': key,
                'Authorization': 'Bearer ' + key,
                'Content-Type': 'application/json',
                'Prefer': 'return=representation'
            },
            payload: JSON.stringify(body)
        }, null];
    }

} else {
    if (ctx.segundos_parado > 0 && ctx.segundos_parado < UMBRAL) {
        node.warn('Microparada ignorada: ' + ctx.segundos_parado + 's');
    }
    if (ctx.parada_id) {
        const parada_id = ctx.parada_id;
        ctx.parada_id = null;
        ctx.segundos_parado = 0;
        ctx.inicio_sensor = null;
        flow.set('trapiche_ctx', ctx);
        node.status({fill:'green', shape:'dot', text:'Moliendo — parada cerrada'});
        return [null, {
            method: 'PATCH',
            url: url + '/rest/v1/paradas_inferidas?id=eq.' + parada_id,
            headers: {
                'apikey': key,
                'Authorization': 'Bearer ' + key,
                'Content-Type': 'application/json'
            },
            payload: JSON.stringify({ fin: new Date().toISOString() })
        }];
    }
    ctx.segundos_parado = 0;
    ctx.inicio_sensor = null;
    node.status({fill:'green', shape:'dot', text:'Moliendo'});
}

flow.set('trapiche_ctx', ctx);
return null;

const ctx = flow.get('trapiche_ctx') || {};
if (Array.isArray(msg.payload) && msg.payload[0]) {
    ctx.parada_id = msg.payload[0].id;
    flow.set('trapiche_ctx', ctx);
    node.status({fill:'red', shape:'dot', text:'Parada id=' + ctx.parada_id + ' abierta'});
    node.warn('✅ Parada inferida registrada: id=' + ctx.parada_id);
}
return null;
